'use strict';

var escape = require('../helpers/escape');

function _render(context, options) {

	var $ = context.jQuery,
		PubSub = context.PubSub;

	//Create each option
	var renderedOptions = [],
		option,
		attribs,
		text,
		value;

	for (var i = 0; i < options.options.length; i++) {
		option = options.options[i];
		attribs = [];
		text = null;
		value = null;

		for (var key in option) {
			var val = option[key];

			switch (key) {
				case 'text':
					text = val;
					break;
				case 'value':
					value = val;
					break;
				default:
					attribs.push('data-' + key + '="' + val + '"');
					break;
			}
		}

		if (text) {
			if (typeof value === 'undefined') {
				value = text;
			}
		} else if (value) {
			text = value;
		} else {
			continue; //no text or value, skip
		}

		renderedOptions.push('<option value="' + value + '" ' + attribs.join(' ') + '>' + text + '</option>');
	}

	//Create the question
	var question = options.question ? options.question : 'combo',
		name = options.name ? options.name : question,
		attrib = escape.htmlAttributeEscape(JSON.stringify(options), { singleQuotes: true });

	//HTML
	var $html = $(
		'<div class="form-group">' +
		'<h3>' + question + '</h3>' +
		'<select class="form-control f3-combo" name="' + name + '" data-options=\'' + attrib + '\'>' +
			renderedOptions.join('') +
		'</select>' +
		'</div>'
	);

	//Bind change
	$html.find('select').on('change', function() {

		var self = this;

		var $selected = $(this).find(':selected'),
			hide = $selected.data('hide') ? $selected.data('hide').split(',') : false,
			show = $selected.data('show') ? $selected.data('show').split(',') : false;

		if (hide) {
			hide.forEach(function(name){
				_findBranchSibling($(self.form), name).hide();
			});
		}

		if (show) {
			show.forEach(function(name){
				_findBranchSibling($(self.form), name).show();
			});
		}

		//Publish the event
		PubSub.publish('f3.combo', {
			'trigger': self,
			'event': 'change'
		});

	}).on('click', function() {

		//Publish the event
		PubSub.publish('f3.combo', {
			'trigger': this,
			'event': 'click'
		});

	});

	return $html;
}

function _read(options, value) {

	var result;

	for (var i = 0; i < options.options.length; i++) {
		var option = options.options[i],
			optValue = option.value,
			optText = option.text;

		if (optText) {
			if (typeof optValue === 'undefined') {
				optValue = optText;
			}
		} else if (optValue) {
			optText = optValue;
		} else {
			continue; //no text or value, skip
		}

		if (optValue === value) {
			result = {
				text: optText,
				value: optValue
			};
			break;
		}
	}

	if (!result) {
		return null;
	}

	result.question = options.question || 'combo';
	result.name = options.name || options.question;

	return result;

}

function _findBranchSibling($branch, name) {
	return $branch
		.find('[name="' + name + '"]')
		.parent('.form-group');
}

module.exports = {
	render: _render,
	read: _read,
	name: 'combo'
};
